import {makeQuestion} from './catalog.js';
export const reading=[], readingStimuli=[];
export function passage(title,text,items,split='practice'){
 const id=`R-P${String(readingStimuli.length+1).padStart(2,'0')}`;
 readingStimuli.push({id,type:'reading',title,text,split,source:'Naskah orisinal proyek, 2026',permission:'original-project-content',reviewStatus:'editorial-draft'});
 for(const [type,prompt,correct,wrong,evidence,why] of items){const n=reading.length+1;reading.push(makeQuestion(`R${String(n).padStart(3,'0')}`,'reading',`reading-${type}`,split,prompt,correct,wrong,evidence,why,{stimulus:id}));}
}
passage('A cooler route to school',`A coastal town planted trees along two routes used by children walking to school. The planners expected shade to improve comfort, but they also wanted to know whether the trees changed the temperature of nearby buildings. Sensors were attached to shaded and unshaded walls of similar construction. Measurements were taken at the same hour on clear afternoons for six weeks.

The shaded walls were consistently cooler. However, the air measured a few meters away showed much smaller differences. The researchers cautioned that a cool wall did not necessarily mean that an entire street had become cooler. Wind moved air between the two routes, making local effects difficult to isolate.

Rather than treating the project as a failure, the town revised its goal. It would prioritize shade at waiting areas and crossings, where people remained still in direct sunlight. The study thus changed where new trees would be planted, even though it did not establish a large reduction in street-wide air temperature.`,[
 ['main','What is the passage mainly about?',['How measurements refined a tree-planting strategy','Bacaan bergerak dari tujuan awal, temuan, ke revisi penempatan pohon.'],[['Why coastal trees grow unusually quickly','Laju pertumbuhan pohon tidak dibahas.'],['How school walls were constructed','Kesamaan konstruksi hanya kontrol penelitian.'],['Why the town removed its street trees','Pohon tidak dicabut; penempatan baru diubah.']],'The study thus changed where new trees would be planted.','Temuan membatasi klaim pendinginan tetapi membantu memperbaiki strategi.'],
 ['detail','Why were walls of similar construction selected?',['To make the shaded and unshaded measurements more comparable','Konstruksi serupa mengurangi perbedaan selain naungan.'],[['To prove that all buildings had identical temperatures','Temperatur justru dibandingkan, bukan diasumsikan identik.'],['To measure tree growth at night','Pengukuran dilakukan sore hari, bukan pertumbuhan pohon.'],['To determine how much the walls cost','Biaya dinding tidak diperiksa.']],'Sensors were attached to shaded and unshaded walls of similar construction.','Pemilihan bahan serupa membantu membandingkan pengaruh naungan.'],
 ['reference','The word “they” in the first paragraph refers to',['the planners','Planners adalah pihak yang memiliki dua tujuan penelitian.'],[['the children','Anak-anak menggunakan rute, bukan merancang pengukuran.'],['the trees','Pohon tidak memiliki tujuan penelitian.'],['the sensors','Sensor baru diperkenalkan sesudah kalimat ini.']],'The planners expected shade to improve comfort, but they also wanted to know…','They melanjutkan subjek the planners.'],
 ['vocabulary','The word “isolate” is closest in meaning to',['separate from other influences','Angin mencampur udara sehingga efek lokal sulit dipisahkan.'],[['increase rapidly','Tidak ada makna peningkatan laju.'],['record permanently','Masalahnya bukan penyimpanan catatan.'],['explain to children','Tidak ada komunikasi anak dalam konteks ini.']],'Wind moved air between the two routes, making local effects difficult to isolate.','Isolate berarti memisahkan efek pohon dari pengaruh lain.'],
 ['inference','Which conclusion is best supported?',['A project can guide decisions without confirming its broadest expectation','Revisi lokasi tetap berguna meski pendinginan menyeluruh tidak terbukti.'],[['Trees cannot improve pedestrian comfort','Dinding yang lebih sejuk dan prioritas naungan justru mendukung manfaat lokal.'],['Wind always makes temperature research impossible','Bacaan hanya menyebut kesulitan mengisolasi efek lokal.'],['The unshaded route should be closed permanently','Tidak ada rekomendasi penutupan rute.']],'Rather than treating the project as a failure, the town revised its goal.','Simpulan terbatas pada pemanfaatan hasil untuk keputusan.']
],'diagnostic');
passage('The missing pages',`When a university library received the papers of a retired geologist, several field notebooks appeared to be incomplete. Pages describing a survey of a volcanic island were absent, while later entries referred to observations made there. An archivist initially suspected that the pages had been removed because the survey had failed.

A second examination revealed a less dramatic explanation. Small numbers written in pencil did not match the sequence of the bound volumes. The geologist had numbered individual expeditions rather than notebooks, and a binder had later arranged the loose pages by size. Notes from the island had therefore been placed in a larger volume labeled with a different year.

The library kept the physical arrangement intact because it documented the collection's history. Instead, it created a digital index linking related pages across volumes. Researchers could now reconstruct the survey without assuming that the date on a cover accurately described every page inside. The case illustrates why an archive's organization is itself evidence that must be interpreted.`,[
 ['main','Which title best fits the passage?',['Recovering a Survey through Archival Context','Bacaan tentang penemuan ulang catatan melalui cara arsip disusun.'],[['The Failure of a Volcanic Expedition','Kegagalan hanya dugaan awal yang tidak terbukti.'],['A Guide to Binding Modern Books','Teknik menjilid bukan tujuan bacaan.'],['Why Universities Reject Personal Papers','Perpustakaan menerima koleksi, bukan menolak.']],'Notes from the island had therefore been placed in a larger volume.','Organisasi koleksi menjelaskan halaman yang tampak hilang.'],
 ['detail','How had the binder arranged the loose pages?',['According to their size','Kriteria pengikat adalah ukuran fisik halaman.'],[['By the date on each notebook cover','Tanggal sampul justru menyesatkan.'],['By the success of each expedition','Hasil ekspedisi tidak dipakai sebagai urutan.'],['Alphabetically by island name','Tidak ada urutan alfabetis disebutkan.']],'a binder had later arranged the loose pages by size','Rincian ini eksplisit dalam paragraf kedua.'],
 ['reference','The word “it” in “it created a digital index” refers to',['the library','Perpustakaan mengambil tindakan alternatif setelah mempertahankan susunan fisik.'],[['the survey','Survei tidak menciptakan indeks.'],['the larger volume','Volume buku tidak melakukan tindakan.'],['the collection’s history','Sejarah merupakan alasan, bukan pelaku.']],'The library kept the physical arrangement intact… Instead, it created a digital index.','Subjek tindakan tetap the library.'],
 ['inference','Why did the library avoid rearranging the physical pages?',['The existing arrangement preserved information about the collection','Susunan merupakan bagian dari sejarah koleksi.'],[['The missing pages had not been found','Halaman sudah ditemukan dalam volume lain.'],['Researchers were forbidden to compare volumes','Indeks justru menghubungkan volume.'],['Every cover date was known to be correct','Bacaan memperingatkan tanggal sampul mungkin tidak tepat.']],'because it documented the collection’s history','Mengubah susunan akan menghilangkan informasi historis pengarsipan.'],
 ['purpose','Why is the archivist’s initial suspicion mentioned?',['To contrast an early interpretation with a later explanation','Dugaan kegagalan dipertentangkan dengan bukti organisasi arsip.'],[['To establish that the geologist falsified data','Tidak ada pemalsuan disebutkan.'],['To recommend destroying unreliable notes','Catatan dipertahankan dan diindeks.'],['To argue that pencil marks are meaningless','Angka pensil justru memecahkan masalah.']],'A second examination revealed a less dramatic explanation.','Struktur dugaan awal → bukti baru menunjukkan perubahan interpretasi.']
],'diagnostic');
passage('Seeds beneath the pavement',`During the repair of a town square, workers uncovered soil that had been sealed beneath paving stones for nearly forty years. A botanist collected samples from three depths and placed them in trays in a greenhouse. Some trays were watered regularly; others received brief wet periods separated by long dry intervals. The experiment did not attempt to recreate the exact conditions of the old square. It tested whether any seeds in the buried soil were still capable of germination.

Seedlings appeared in the regularly watered trays, mostly from the shallowest samples. No seedlings emerged from the deepest layer. The botanist warned that this absence did not prove that every seed at that depth was dead. Some species require temperature changes or disturbance before they germinate, neither of which the greenhouse treatment provided.

The findings interested local gardeners, but the botanist resisted describing the buried soil as a complete historical record of the square's vegetation. Plants differ in how long their seeds survive, so the species that emerged represented only a selective trace of the past.`,[
 ['main','What is the main point of the passage?',['Buried seeds can reveal the past, but the evidence has limits','Hasil perkecambahan memberi jejak selektif, bukan gambaran lengkap.'],[['All seeds survive under paving stones','Tidak semua biji tumbuh dan tidak ada klaim universal.'],['Greenhouses reproduce historical conditions exactly','Paragraf satu secara eksplisit menolak tujuan itu.'],['Town squares should never be paved','Rekomendasi kebijakan itu tidak dibahas.']],'the species that emerged represented only a selective trace of the past','Temuan dan dua batas interpretasi mendominasi bacaan.'],
 ['detail','What did the greenhouse experiment test?',['Whether buried seeds could still germinate','Pertanyaan penelitian menyangkut kemampuan berkecambah.'],[['How quickly paving stones decay','Batu bukan objek eksperimen.'],['Which plants grew in every year of the square’s history','Eksperimen tidak menghasilkan catatan tahunan.'],['Whether gardeners preferred native plants','Preferensi tukang kebun tidak diukur.']],'It tested whether any seeds in the buried soil were still capable of germination.','Jawaban sama dengan tujuan yang dinyatakan.'],
 ['vocabulary','“Disturbance” in the second paragraph most nearly means',['physical disruption of the soil','Gangguan fisik dapat memicu germination bersama perubahan suhu.'],[['public disagreement','Konteksnya tanah dan biji, bukan pendapat.'],['a lack of interest','Minat bukan kondisi perkecambahan.'],['an official prohibition','Tidak ada larangan resmi dalam eksperimen.']],'Some species require temperature changes or disturbance before they germinate.','Makna ditentukan konteks kondisi lingkungan.'],
 ['inference','Why would the deepest layer need further testing?',['Its seeds might need conditions not supplied in the experiment','Ketiadaan kecambah belum membuktikan semua biji mati.'],[['It certainly contains more living seeds than the top layer','Jumlah hidup tidak diketahui.'],['It received no water in any tray','Perlakuan air diterapkan pada sampel, bukan dinyatakan tidak ada.'],['It was collected from a different town','Semua sampel berasal dari alun-alun yang sama.']],'neither of which the greenhouse treatment provided','Perlu pengujian kondisi pemicu lain sebelum simpulan kuat.'],
 ['purpose','Why does the author mention differences in seed survival?',['To explain why emerging species cannot represent all past vegetation','Daya tahan berbeda membuat catatan bias pada spesies tertentu.'],[['To prove that the square was never planted','Tidak ada bukti bahwa tidak pernah ditanami.'],['To compare the costs of gardening tools','Biaya alat tidak dibahas.'],['To show that regular watering kills all seeds','Sebagian justru tumbuh dalam tray yang rutin disiram.']],'Plants differ in how long their seeds survive.','Alasan ini membatasi representasi sejarah vegetasi.']
]);
passage('An index of silence',`A museum digitizing early sound recordings faced an unusual problem: its catalog described the music but rarely mentioned the sounds between performances. On one cylinder recording, for example, a vendor's call could be heard before a song began. Another preserved a train whistle that briefly interrupted a speaker. These sounds had once been treated as defects, and some earlier copies had removed them.

The new project retained the interruptions and added searchable descriptions. Historians could use them to investigate how recording sessions interacted with everyday life. A whistle might help identify a location, although the curators stressed that it would not establish one without additional evidence. Several towns used similar railway signals.

Keeping the full recordings also changed the workload. Short pieces required more detailed catalog entries, and volunteers needed guidance on distinguishing an audible event from an interpretation. The catalog could state that a bell was heard, for instance, without claiming that it came from a particular church. The project valued incidental sound while making its uncertainty explicit.`,[
 ['main','The passage mainly discusses',['a change in how incidental recorded sounds are documented','Museum kini mempertahankan interupsi dan mendeskripsikannya dengan hati-hati.'],[['a method for eliminating every recording defect','Interupsi dipertahankan, bukan dihilangkan.'],['the invention of railway signals','Sinyal hanya contoh bukti yang terbatas.'],['a competition among museum volunteers','Relawan bekerja mengatalog, bukan berlomba.']],'The new project retained the interruptions and added searchable descriptions.','Perubahan kebijakan dokumentasi adalah fokus.'],
 ['detail','What had some earlier copies done?',['Removed sounds between performances','Bunyi yang dianggap cacat dihapus dari sebagian salinan.'],[['Replaced every song with a speech','Tidak ada penggantian lagu dengan pidato.'],['Added modern train whistles','Peluit merupakan suara asli, bukan tambahan modern.'],['Identified the church behind every bell','Proyek justru menghindari klaim sumber tanpa bukti.']],'some earlier copies had removed them','Them menunjuk bunyi insidental yang dianggap cacat.'],
 ['reference','“Them” in “Historians could use them” refers to',['the interruptions','Suara insidental digunakan sebagai sumber sejarah.'],[['the volunteers','Relawan belum diperkenalkan pada paragraf ini.'],['the railway towns','Kota baru disebut setelah kalimat ini.'],['the earlier copies','Salinan terdahulu malah menghilangkan bunyi relevan.']],'retained the interruptions… Historians could use them','Konteks tindakan mempertahankan interupsi memberi antecedent.'],
 ['inference','Which catalog entry follows the project’s guidance?',['A bell sounds briefly before the speaker begins','Entri ini melaporkan hal yang terdengar tanpa mengarang sumber.'],[['The bell proves the recording was made in the old cathedral','Bunyi saja tidak membuktikan gereja tertentu.'],['The train whistle identifies the town beyond doubt','Sinyal serupa digunakan beberapa kota.'],['The vendor must have opposed the performance','Motif vendor tidak dapat diketahui dari panggilan.']],'distinguishing an audible event from an interpretation','Pisahkan observasi suara dan atribusi yang membutuhkan bukti lain.'],
 ['vocabulary','The word “incidental” is closest in meaning to',['occurring alongside the intended subject','Bunyi datang di sela penampilan utama.'],[['carefully rehearsed','Bunyi digambarkan sebagai interupsi, bukan latihan.'],['completely inaudible','Bunyi dapat didengar dan dideskripsikan.'],['legally prohibited','Tidak ada larangan hukum dalam konteks.']],'sounds between performances','Incidental berarti menyertai, bukan inti rekaman.']
]);
