 ['detail','What had the removed mud contained?',['Seeds and plant fragments','Lumpur menyimpan bahan awal regenerasi.'],[['Only artificial waste','Tidak dinyatakan hanya sampah.'],['The volunteers’ measuring baskets','Keranjang baru dipasang setelah evaluasi.'],['A layer of commercial fertilizer','Tidak ada pupuk yang telah ditambahkan.']],'a store of seeds and small plant fragments','Rincian menjelaskan lambatnya pertumbuhan.'],
 ['inference','Why leave some sections unplanted?',['To compare growth with and without introduced plants','Area pembanding membantu menilai intervensi.'],[['To ensure those sections could never support life','Bukan tujuan pemusnahan.'],['To increase the fertilizer concentration','Pupuk tidak menjadi perlakuan.'],['To make the whole pond equally deep','Kedalaman tidak diseragamkan lewat penanaman.']],'left other sections unplanted for comparison','Tujuan perbandingan eksplisit mendukung inferensi.'],
 ['vocabulary','“Favor” most nearly means',['encourage the growth of','Nutrisi mungkin menguntungkan alga.'],[['express personal affection for','Konteks proses ekologi, bukan perasaan.'],['remove from the pond','Kebalikannya, alga dapat tumbuh.'],['measure the age of','Bukan pengukuran umur.']],'might favor algae instead','Makna mendukung pertumbuhan kelompok tertentu.'],
 ['purpose','Why recommend another season of observation?',['To assess recovery beyond the first encouraging signs','Penyebaran awal belum membuktikan hasil jangka panjang.'],[['To deny that any species had spread','Penyebaran sudah diamati.'],['To postpone every planting indefinitely','Penanaman sudah dilakukan.'],['To wait until all water became muddy again','Bukan tujuan mengeruhkan kembali.']],'several species had spread… another full season','Saran menyatakan kehati-hatian terhadap bukti awal.']
